/**
 * @file bench_c_runner.c
 * @brief Standalone C11 Benchmark Runner for Prequential Hoeffding Tree Evaluation.
 *
 * Implements:
 * - Deterministic ingestion of synthetic CSV streams generated by generate_streams.py.
 * - Test-Then-Train prequential evaluation measuring accuracy, tree topology growth,
 *   memory consumption (<= 1 MB), and high-resolution timing (clock_gettime).
 * - Periodic checkpoint logging (every 1000 samples) and JSON export for
 *   direct parity comparison with River.
 *
 * Strictly adheres to C11 (-std=c11 -Wall -Wextra -Werror -pedantic) and zero malloc in runtime.
 */

#define _POSIX_C_SOURCE 199309L

#include "ht_tree.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define MAX_LINE_LEN 2048
#define MAX_CHECKPOINTS 1024

typedef struct {
    uint32_t sample;
    double   accuracy;
    uint16_t n_nodes;
    uint16_t n_active_leaves;
    uint16_t n_inactive_leaves;
    uint16_t n_decision_nodes;
    uint16_t max_depth;
    size_t   bytes_used;
    double   avg_us_per_sample;
} bench_checkpoint_t;

/* Static memory allocations (BSS) - zero malloc in runtime */
static ht_tree_t tree_instance;
static bench_checkpoint_t checkpoints[MAX_CHECKPOINTS];
static size_t num_checkpoints = 0;

static double get_time_diff_us(struct timespec start, struct timespec end) {
    double sec = (double)(end.tv_sec - start.tv_sec);
    double nsec = (double)(end.tv_nsec - start.tv_nsec);
    return (sec * 1000000.0) + (nsec / 1000.0);
}

static void print_usage(const char *prog_name) {
    fprintf(stderr, "Usage: %s <dataset.csv> [options]\n", prog_name);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  --criterion <info_gain|gini>      Split criterion (default: info_gain)\n");
    fprintf(stderr, "  --leaf <nba|nb|mc>                Leaf prediction strategy (default: nba)\n");
    fprintf(stderr, "  --grace-period <N>                Grace period between splits (default: 200)\n");
    fprintf(stderr, "  --delta <D>                       Split confidence parameter (default: 1e-7)\n");
    fprintf(stderr, "  --tau <T>                         Tie-breaking threshold (default: 0.05)\n");
    fprintf(stderr, "  --checkpoint-interval <N>         Interval between checkpoints (default: 1000)\n");
    fprintf(stderr, "  --json <file.json>                Save JSON benchmark results\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage(argv[0]);
        return 1;
    }

    const char *csv_path = argv[1];
    ht_criterion_type_t criterion = HT_CRIT_INFO_GAIN;
    ht_leaf_pred_t leaf_pred = HT_LEAF_NBA;
    uint16_t grace_period = 200;
    double delta_val = 1e-7;
    double tau_val = 0.05;
    uint32_t checkpoint_interval = 1000;
    const char *json_out_path = NULL;

    for (int i = 2; i < argc; ++i) {
        if (strcmp(argv[i], "--criterion") == 0 && i + 1 < argc) {
            if (strcmp(argv[++i], "gini") == 0) {
                criterion = HT_CRIT_GINI;
            } else {
                criterion = HT_CRIT_INFO_GAIN;
            }
        } else if (strcmp(argv[i], "--leaf") == 0 && i + 1 < argc) {
            const char *leaf_str = argv[++i];
            if (strcmp(leaf_str, "mc") == 0) {
                leaf_pred = HT_LEAF_MC;
            } else if (strcmp(leaf_str, "nb") == 0) {
                leaf_pred = HT_LEAF_NB;
            } else {
                leaf_pred = HT_LEAF_NBA;
            }
        } else if (strcmp(argv[i], "--grace-period") == 0 && i + 1 < argc) {
            grace_period = (uint16_t)atoi(argv[++i]);
        } else if (strcmp(argv[i], "--delta") == 0 && i + 1 < argc) {
            delta_val = atof(argv[++i]);
        } else if (strcmp(argv[i], "--tau") == 0 && i + 1 < argc) {
            tau_val = atof(argv[++i]);
        } else if (strcmp(argv[i], "--checkpoint-interval") == 0 && i + 1 < argc) {
            checkpoint_interval = (uint32_t)atoi(argv[++i]);
        } else if (strcmp(argv[i], "--json") == 0 && i + 1 < argc) {
            json_out_path = argv[++i];
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
            print_usage(argv[0]);
            return 1;
        }
    }

    FILE *fp = fopen(csv_path, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open dataset file: %s\n", csv_path);
        return 1;
    }

    char line_buf[MAX_LINE_LEN];
    char stream_name[64] = "unknown";
    uint32_t header_n_samples = 0;
    uint32_t n_features = 0;
    uint32_t n_classes = 0;
    ht_feature_type_t feat_types[HT_MAX_FEATURES];
    for (uint32_t f = 0; f < HT_MAX_FEATURES; ++f) {
        feat_types[f] = HT_FEAT_NUMERIC;
    }

    if (!fgets(line_buf, sizeof(line_buf), fp)) {
        fprintf(stderr, "Error: Empty CSV file\n");
        fclose(fp);
        return 1;
    }

    if (line_buf[0] == '#') {
        char *token = strtok(line_buf + 1, " \t\r\n");
        while (token) {
            if (strncmp(token, "stream=", 7) == 0) {
                strncpy(stream_name, token + 7, sizeof(stream_name) - 1);
            } else if (strncmp(token, "n_samples=", 10) == 0) {
                header_n_samples = (uint32_t)atoi(token + 10);
            } else if (strncmp(token, "n_features=", 11) == 0) {
                n_features = (uint32_t)atoi(token + 11);
            } else if (strncmp(token, "n_classes=", 10) == 0) {
                n_classes = (uint32_t)atoi(token + 10);
            } else if (strncmp(token, "feature_types=", 14) == 0) {
                char *types_str = token + 14;
                char *t_tok = strtok(types_str, ",");
                uint32_t f_idx = 0;
                while (t_tok && f_idx < HT_MAX_FEATURES) {
                    feat_types[f_idx++] = (atoi(t_tok) == 1) ? HT_FEAT_CATEGORICAL : HT_FEAT_NUMERIC;
                    t_tok = strtok(NULL, ",");
                }
            }
            token = strtok(NULL, " \t\r\n");
        }
    } else {
        fprintf(stderr, "Error: CSV header metadata (# stream=...) missing\n");
        fclose(fp);
        return 1;
    }

    if (n_features == 0 || n_features > HT_MAX_FEATURES || n_classes < 2 || n_classes > HT_MAX_CLASSES) {
        fprintf(stderr, "Error: Invalid features (%u) or classes (%u) for HT limits (F<=%u, C<=%u)\n",
                n_features, n_classes, HT_MAX_FEATURES, HT_MAX_CLASSES);
        fclose(fp);
        return 1;
    }

    /* Configure Hoeffding Tree */
    ht_config_params_t params;
    ht_default_params(&params, (uint8_t)n_features, (uint8_t)n_classes);
    for (uint8_t f = 0; f < n_features; ++f) {
        params.feature_types[f] = feat_types[f];
    }
    params.criterion = criterion;
    params.leaf_prediction = leaf_pred;
    params.grace_period = grace_period;
    params.delta = (ht_float_t)delta_val;
    params.tau = (ht_float_t)tau_val;
    params.min_branch_fraction = (ht_float_t)0.01;
    params.max_share_to_split = (ht_float_t)0.99;
    params.nb_threshold = (ht_float_t)0.0;
    params.merit_preprune = true;

    ht_status_t init_status = ht_tree_init(&tree_instance, &params);
    if (init_status != HT_OK) {
        fprintf(stderr, "Error: Failed to initialize Hoeffding Tree: %d\n", init_status);
        fclose(fp);
        return 1;
    }

    const char *mode_str = (sizeof(ht_float_t) == 8) ? "float64 (double)" : "float32 (single)";

    printf("====================================================================================\n");
    printf(" C11 Hoeffding Tree Prequential Benchmark Runner\n");
    printf(" Stream:          %s (features=%u, classes=%u, expected_samples=%u)\n",
           stream_name, n_features, n_classes, header_n_samples);
    printf(" Precision Mode:  %s (tree size = %zu bytes, %.1f KB)\n",
           mode_str, sizeof(ht_tree_t), (double)sizeof(ht_tree_t) / 1024.0);
    printf(" Hyperparameters: Criterion=%s, Leaf=%s, GracePeriod=%u, Delta=%.1e, Tau=%.3f\n",
           (criterion == HT_CRIT_INFO_GAIN) ? "InfoGain" : "Gini",
           (leaf_pred == HT_LEAF_NBA) ? "NBA" : ((leaf_pred == HT_LEAF_NB) ? "NB" : "MC"),
           grace_period, delta_val, tau_val);
    printf("====================================================================================\n");
    printf(" %-8s | %-10s | %-6s | %-7s | %-7s | %-6s | %-10s | %-10s\n",
           "Sample", "Accuracy", "Nodes", "Active", "Inact.", "Depth", "RAM (KB)", "Time/s (us)");
    printf("------------------------------------------------------------------------------------\n");

    uint32_t sample_idx = 0;
    uint32_t correct_preds = 0;
    double total_elapsed_us = 0.0;
    ht_value_t x[HT_MAX_FEATURES];

    while (fgets(line_buf, sizeof(line_buf), fp)) {
        if (line_buf[0] == '#' || line_buf[0] == '\n' || line_buf[0] == '\r') {
            continue;
        }

        /* Parse comma-separated feature values and label */
        char *saveptr = NULL;
        char *tok = strtok_r(line_buf, ",\r\n", &saveptr);
        uint8_t f_idx = 0;
        uint8_t y_label = 0;

        while (tok && f_idx < n_features) {
            double val = atof(tok);
            if (feat_types[f_idx] == HT_FEAT_CATEGORICAL) {
                x[f_idx].cat = (int32_t)val;
            } else {
                x[f_idx].num = (ht_float_t)val;
            }
            f_idx++;
            tok = strtok_r(NULL, ",\r\n", &saveptr);
        }

        if (tok) {
            y_label = (uint8_t)atoi(tok);
        } else {
            continue; /* Incomplete line */
        }

        /* Prequential Evaluation: 1. Predict (Test) */
        struct timespec t_start, t_end;
        clock_gettime(CLOCK_MONOTONIC, &t_start);

        uint8_t y_pred = ht_tree_predict(&tree_instance, x);
        if (y_pred == y_label) {
            correct_preds++;
        }

        /* 2. Train */
        ht_status_t learn_status = ht_tree_learn_one(&tree_instance, x, y_label, (ht_float_t)1.0);
        if (learn_status != HT_OK) {
            fprintf(stderr, "Error during ht_tree_learn_one at sample %u: %d\n", sample_idx, learn_status);
            fclose(fp);
            return 1;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_end);
        total_elapsed_us += get_time_diff_us(t_start, t_end);
        sample_idx++;

        /* Checkpoint evaluation */
        if (sample_idx % checkpoint_interval == 0) {
            double curr_acc = (double)correct_preds / (double)sample_idx;
            uint16_t total_nodes = tree_instance.n_active_leaves +
                                  tree_instance.n_inactive_leaves +
                                  tree_instance.n_decision_nodes;
            size_t bytes_used = ht_memory_bytes_used(&tree_instance.memory);
            double avg_us = total_elapsed_us / (double)sample_idx;

            printf(" %-8u | %9.4f%% | %-6u | %-7u | %-7u | %-6u | %9.1f | %10.2f\n",
                   sample_idx, curr_acc * 100.0, total_nodes,
                   tree_instance.n_active_leaves, tree_instance.n_inactive_leaves,
                   tree_instance.max_depth_seen, (double)bytes_used / 1024.0, avg_us);
            fflush(stdout);

            if (num_checkpoints < MAX_CHECKPOINTS) {
                checkpoints[num_checkpoints].sample = sample_idx;
                checkpoints[num_checkpoints].accuracy = curr_acc;
                checkpoints[num_checkpoints].n_nodes = total_nodes;
                checkpoints[num_checkpoints].n_active_leaves = tree_instance.n_active_leaves;
                checkpoints[num_checkpoints].n_inactive_leaves = tree_instance.n_inactive_leaves;
                checkpoints[num_checkpoints].n_decision_nodes = tree_instance.n_decision_nodes;
                checkpoints[num_checkpoints].max_depth = tree_instance.max_depth_seen;
                checkpoints[num_checkpoints].bytes_used = bytes_used;
                checkpoints[num_checkpoints].avg_us_per_sample = avg_us;
                num_checkpoints++;
            }
        }
    }

    fclose(fp);

    /* Final statistics */
    double final_accuracy = (sample_idx > 0) ? ((double)correct_preds / (double)sample_idx) : 0.0;
    uint16_t final_nodes = tree_instance.n_active_leaves +
                          tree_instance.n_inactive_leaves +
                          tree_instance.n_decision_nodes;
    size_t final_bytes = ht_memory_bytes_used(&tree_instance.memory);
    double final_avg_us = (sample_idx > 0) ? (total_elapsed_us / (double)sample_idx) : 0.0;

    printf("------------------------------------------------------------------------------------\n");
    printf(" Summary: Samples=%u, Accuracy=%.4f%%, Nodes=%u, ActiveLeaves=%u, RAM=%.1f KB (<=1024 KB), Avg=%.2f us/sample\n",
           sample_idx, final_accuracy * 100.0, final_nodes, tree_instance.n_active_leaves,
           (double)final_bytes / 1024.0, final_avg_us);
    printf("====================================================================================\n");

    /* Export JSON if requested */
    if (json_out_path) {
        FILE *jfp = fopen(json_out_path, "w");
        if (!jfp) {
            fprintf(stderr, "Warning: Could not open output JSON file: %s\n", json_out_path);
        } else {
            fprintf(jfp, "{\n");
            fprintf(jfp, "  \"stream\": \"%s\",\n", stream_name);
            fprintf(jfp, "  \"precision\": \"%s\",\n", (sizeof(ht_float_t) == 8) ? "double" : "float");
            fprintf(jfp, "  \"n_samples\": %u,\n", sample_idx);
            fprintf(jfp, "  \"n_features\": %u,\n", n_features);
            fprintf(jfp, "  \"n_classes\": %u,\n", n_classes);
            fprintf(jfp, "  \"final_accuracy\": %.6f,\n", final_accuracy);
            fprintf(jfp, "  \"final_nodes\": %u,\n", final_nodes);
            fprintf(jfp, "  \"final_active_leaves\": %u,\n", tree_instance.n_active_leaves);
            fprintf(jfp, "  \"final_inactive_leaves\": %u,\n", tree_instance.n_inactive_leaves);
            fprintf(jfp, "  \"final_decision_nodes\": %u,\n", tree_instance.n_decision_nodes);
            fprintf(jfp, "  \"final_max_depth\": %u,\n", tree_instance.max_depth_seen);
            fprintf(jfp, "  \"final_bytes_used\": %zu,\n", final_bytes);
            fprintf(jfp, "  \"total_time_us\": %.2f,\n", total_elapsed_us);
            fprintf(jfp, "  \"avg_time_per_sample_us\": %.3f,\n", final_avg_us);
            fprintf(jfp, "  \"checkpoints\": [\n");

            for (size_t c = 0; c < num_checkpoints; ++c) {
                fprintf(jfp, "    {\n");
                fprintf(jfp, "      \"sample\": %u,\n", checkpoints[c].sample);
                fprintf(jfp, "      \"accuracy\": %.6f,\n", checkpoints[c].accuracy);
                fprintf(jfp, "      \"n_nodes\": %u,\n", checkpoints[c].n_nodes);
                fprintf(jfp, "      \"n_active_leaves\": %u,\n", checkpoints[c].n_active_leaves);
                fprintf(jfp, "      \"n_inactive_leaves\": %u,\n", checkpoints[c].n_inactive_leaves);
                fprintf(jfp, "      \"n_decision_nodes\": %u,\n", checkpoints[c].n_decision_nodes);
                fprintf(jfp, "      \"max_depth\": %u,\n", checkpoints[c].max_depth);
                fprintf(jfp, "      \"bytes_used\": %zu,\n", checkpoints[c].bytes_used);
                fprintf(jfp, "      \"avg_us_per_sample\": %.3f\n", checkpoints[c].avg_us_per_sample);
                fprintf(jfp, "    }%s\n", (c + 1 < num_checkpoints) ? "," : "");
            }

            fprintf(jfp, "  ]\n");
            fprintf(jfp, "}\n");
            fclose(jfp);
            printf("Saved benchmark JSON to: %s\n", json_out_path);
        }
    }

    return 0;
}
